#include <stdio.h>
int main(void) {
    int n, a[1000];
    if (scanf("%d", &n) != 1) return 0;
    for (int i = 0; i < n; i++) scanf("%d", &a[i]);
    for (int i = 0; i < n; i++) {
        for (int j = 0; j + 1 < n - i; j++) {
            if (a[j] > a[j + 1]) { int t = a[j]; a[j] = a[j + 1]; a[j + 1] = t; }
        }
    }
    for (int i = 0; i < n; i++) printf("%s%d", i ? " " : "", a[i]);
    printf("\n");
    return 0;
}

